 verify_protocol();assert read(R/'22_reproducibility/EXPERIMENT_MATRIX_COMPLETE.json')['passed'];assert read(R/'18_independent_verification/INDEPENDENT_PASS.json')['passed'];assert read(R/'18_independent_verification/RUNTIME_PASS.json')['passed'];assert read(R/'10_training_validation/VISIBILITY_SUPPLEMENT_PASS.json')['passed'];figs=rows(R/'SCIENTIFIC_FIGURES.csv');assert len(figs)==35;model=rows(R/'MODEL_PREDICTION_REGISTRY.csv');assert len(model)==299;fact=rows(R/'05_blockwise_interventions/ALL_FIELD_REGISTRY.csv');assert len(fact)==832
 fits=list((R/'11_N3_training').glob('F*_s*/COMPLETED.json'));starts=list((R/'11_N3_training').glob('F*_s*/STARTED.json'));xb=list((R/'12_XGBoost_baseline').glob('F*/COMPLETED.json'));assert len(fits)==len(starts)==10 and len(xb)==5;assert sum(read(p)['steps'] for p in fits)==8320;assert read(R/'10_training_validation/TRAINING_DRY_RUN.json')['steps']==0
