 required_root='QUALIFIED13_SOURCE_REGISTRY.csv DOCUMENTED_PLATE_GROUPS.csv FROZEN_NUMERICAL_TARGET_HASHES.csv HISTORICAL_MODEL_HASHES.csv FEATURE_BLOCK_CONTRACT.csv BLOCK_FACTORIAL_RESULTS.csv BLOCK_MAIN_EFFECTS.csv BLOCK_INTERACTIONS.csv OBSERVABLE_N3_FEATURE_CONTRACT.csv FEATURE_VISIBILITY_AUDIT.csv FEATURE_CONTEXT_CONSISTENCY.csv N3_TRAINING_REGISTRY.csv N3_TRAINING_HISTORIES.csv N3_CHECKPOINT_REGISTRY.csv XGBOOST_TRAINING_REGISTRY.csv XGBOOST_SAMPLE_IDS.csv XGBOOST_PREDICTION_REGISTRY.csv MODEL_PREDICTION_REGISTRY.csv SOURCE_LEVEL_METRICS.csv PLATE_LEVEL_METRICS.csv CONTEXT_ROBUSTNESS_METRICS.csv HIGH95_LOCALIZATION_METRICS.csv PEAK_AND_Q95_ERRORS.csv MODEL_PAIRED_COMPARISONS.csv COMPUTATIONAL_COST_COMPARISON.csv INDEPENDENT_LEAKAGE_AUDIT.csv INDEPENDENT_METRIC_AUDIT.csv'.split()
 required_manuscript='WELDSTRESS_AI_Q1_MANUSCRIPT_DRAFT.md ABSTRACT.md HIGHLIGHTS.md MAIN_CONTRIBUTIONS.md METHODS_REPRODUCIBILITY.md RESULTS_TABLES.csv FIGURE_CAPTIONS.md CLAIM_EVIDENCE_MATRIX.csv LIMITATIONS.md DATA_AVAILABILITY.md CODE_AVAILABILITY.md REFERENCES_VERIFIED.md EDITORIAL_RISK_ASSESSMENT.md'.split();checks=[]
