 manuscript=(R/'20_manuscript/WELDSTRESS_AI_Q1_MANUSCRIPT_DRAFT.md').read_text(encoding='utf8');assert all(text in manuscript for text in ['## Abstract','## 1. Introduction','## 2. Experimental Geometry','## 3. Machine Learning Methods','## 4. Results','## 5. Discussion','## 6. Limitations','## 7. Conclusions','## Data Availability','## Code Availability','## References']);assert len(re.findall(r'^## \d+\.',(R/'R8E16_MASTER_RESEARCH_REPORT.md').read_text(encoding='utf8'),re.M))==62
 for p in (R/'src').glob('*.py'):ast.parse(p.read_text(encoding='utf-8-sig'))
 table(R/'20_manuscript/DELIVERABLE_COMPLETENESS.csv',checks);(R/'20_manuscript/MANUSCRIPT_COMPLETENESS_AUDIT.md').write_text('# Manuscript completeness audit\n\nAll requested manuscript sections,14companion artifacts,62explicit final answers and35figure pairs are present. Results tables are generated from actual source-level fields; numerical independence and runtime memberships are governed by the PASS receipts in18_independent_verification. Five bibliographic records are verified; no dissertation DOI is invented. Figures3/4 are hash-verified historical evidence, labeled reused. The draft remains a draft requiring author metadata, human technical/editorial review, journal formatting and a separately curated public data/code deposit. Q1 acceptance is not guaranteed. Visual review status is stored separately in19_scientific_figures/VISUAL_REVIEW.json.\n',encoding='utf8')
 counts=dict(UTC=now(),targets=13,parent_plates=5,old_checkpoints=20,factorial_fields=832,factorial_query_predictions=832*34200,factorial_workers=20,neural_fits=10,N3_optimizer_steps=8320,dry_backward_checks=1,dry_optimizer_steps=0,XGB_fits=5,XGB_boosting_rounds_per_fold=500,N3_prediction_fields=78,B2_prediction_fields=39,historical_reused_fields=182,model_comparison_fields=299,all_scored_fields=1131,all_scored_point_predictions=1131*34200,new_ANSYS_solves=0,new_FE_meshes=0,new_sources=0,new_targets=0,new_external_predictions=0,architecture_search=0,hyperparameter_search=0,additional_seeds=0,figure_pairs=35,historical_figure_pairs_reused=2,secondary_stitching='NOT_EXECUTED',B0_B1_restricted='NOT_EVALUATED',physical_validation='NOT_ESTABLISHED',independent_external_validation='NOT_ESTABLISHED');write(R/'R8E16_FINAL_COUNTS.json',counts);write(R/'22_reproducibility/PRESEAL_COMPLETE.json',dict(UTC=now(),passed=True,counts=counts,resource=gate()));print(json.dumps(counts,indent=2),flush=True)
